// Dynamically select the right source file based on the bug label
const alert = $('Webhook1').item.json.body?.alerts?.[0];
const bugLabel = alert?.labels?.bug || '';
const alertname = alert?.labels?.alertname || '';

const bugToFile = {
  'partial_commit':       'app/services/payment_processor.py',
  'deadlock':             'app/services/payment_processor.py',
  'idempotency_race':     'app/services/payment_processor.py',
  'fraud_cascade':        'app/services/fraud_detector.py',
  'float_drift':          'app/services/reconciliation.py',
  'webhook_retry_storm':  'app/services/webhook_service.py',
  'memory_leak':          'app/services/transaction_generator.py',
};

const alertToFile = {
  'DBPoolExhausted':           'app/database.py',
  'DBPoolLow':                 'app/database.py',
  'DBConnectionErrors':        'app/database.py',
  'TransactionCacheGrowing':   'app/services/transaction_generator.py',
  'TransactionCacheCritical':  'app/services/transaction_generator.py',
};

const repoRoot = 'n8n support files/test_repo';
const localPath = bugToFile[bugLabel] || alertToFile[alertname] || 'app/services/payment_processor.py';

// URL-encode each path segment (handles spaces in "n8n support files")
const filePath = (repoRoot + '/' + localPath)
  .split('/')
  .map(seg => encodeURIComponent(seg))
  .join('/');

return {
  json: {
    owner: 'vedang0902',
    repository: 'test_repo',
    path: filePath
  }
};

// Parse Prometheus query_range response format:
// { status: 'success', data: { resultType: 'matrix', result: [{ metric: {}, values: [[ts, val], ...] }] } }
const raw = $input.item.json;
let metric_value = 0;
let metric_name = 'unknown';
try {
  const result = raw?.data?.result?.[0];
  if (result) {
    metric_name = result.metric?.__name__ || Object.values(result.metric || {})[0] || 'unknown';
    // values is array of [timestamp, value_string] — take the last point
    const lastPoint = result.values?.slice(-1)?.[0];
    metric_value = lastPoint ? parseFloat(lastPoint[1]) : 0;
  }
} catch (e) {
  metric_value = 0;
}
const webhookJson = $('Webhook1').item.json;
const raw_alert = webhookJson.body || webhookJson;
const amAlert = raw_alert.alerts?.[0];
return {
  json: {
    metrics: {
      metric_name,
      current_value: metric_value,
      source: 'prometheus',
      alertname: amAlert?.labels?.alertname || raw_alert.alertname || 'unknown',
      bug_label: amAlert?.labels?.bug || '',
      severity: amAlert?.labels?.severity || raw_alert.severity || 'unknown'
    },
    raw_alert
  }
};

const item = $input.item.json;
let repo_file_content = '';
if (typeof item.content === 'string') {
  try { repo_file_content = Buffer.from(item.content, 'base64').toString('utf8'); } catch (e) { repo_file_content = item.content; }
} else if (item.data?.content) {
  try { repo_file_content = Buffer.from(item.data.content, 'base64').toString('utf8'); } catch (e) { repo_file_content = item.data.content; }
} else { repo_file_content = typeof item === 'string' ? item : JSON.stringify(item); }
// Capture the file's blob sha too - required later to commit an update to
// this same file via the GitHub Contents API.
const repo_file_sha = item.sha || item.data?.sha || '';
return { json: { repo_file_content, repo_file_sha } };

const items = $input.all();
const metricsItem = items.find(i => i.json.metrics) || items[0];
const repoItem = items.find(i => i.json.repo_file_content !== undefined) || items[1] || items[0];
const metrics = metricsItem?.json?.metrics || {};
const raw_alert = metricsItem?.json?.raw_alert || {};
const repo = repoItem?.json?.repo_file_content ?? '';
const repo_file_sha = repoItem?.json?.repo_file_sha || '';

const amAlert = raw_alert.alerts?.[0];
const incident = amAlert ? {
  name: amAlert.labels?.alertname || 'unknown',
  severity: amAlert.labels?.severity || 'unknown',
  summary: amAlert.annotations?.summary || '',
  started_at: amAlert.startsAt || '',
  status: raw_alert.status || ''
} : {
  name: raw_alert.alertname || raw_alert.title || raw_alert.name || 'unknown',
  severity: raw_alert.severity || raw_alert.priority || 'unknown',
  summary: raw_alert.summary || raw_alert.text || raw_alert.body || '',
  started_at: raw_alert.date || raw_alert.started_at || '',
  status: raw_alert.status || raw_alert.alert_type || ''
};

const bugLabel = amAlert?.labels?.bug || '';
const alertname = amAlert?.labels?.alertname || '';
const bugToFile = {
  'partial_commit':       'app/services/payment_processor.py',
  'deadlock':             'app/services/payment_processor.py',
  'idempotency_race':     'app/services/payment_processor.py',
  'fraud_cascade':        'app/services/fraud_detector.py',
  'float_drift':          'app/services/reconciliation.py',
  'webhook_retry_storm':  'app/services/webhook_service.py',
  'memory_leak':          'app/services/transaction_generator.py',
};
const alertToFile = {
  'DBPoolExhausted':          'app/database.py',
  'DBPoolLow':                'app/database.py',
  'TransactionCacheGrowing':  'app/services/transaction_generator.py',
};
const repoRoot = 'n8n support files/test_repo';
const localPath = bugToFile[bugLabel] || alertToFile[alertname] || 'app/services/payment_processor.py';
const filePath = (repoRoot + '/' + localPath).split('/').map(seg => encodeURIComponent(seg)).join('/');

const fileContent = typeof repo === 'string' ? repo : JSON.stringify(repo);
const promptText = `You are an SRE. Analyze the incident using the provided metrics and code, then propose a fix.

Return valid JSON only with these exact keys:
- root_cause: string describing the root cause
- fix_summary: string (1-2 sentences suitable for a PR description)
- patched_code: string (the FULL corrected content of the file, not a diff)
- risk: one of: low, medium, high

Incident: ${JSON.stringify(incident)}
Metrics: ${JSON.stringify(metrics)}
Current file (${localPath}):
${fileContent}`;

return {
  json: {
    incident,
    metrics,
    repo_file_sha,
    github: { owner: 'vedang0902', repository: 'test_repo', path: filePath, local_path: localPath },
    ai_request: {
      model: 'claude-sonnet-4-6',
      max_tokens: 8192,
      messages: [
        { role: 'user', content: promptText }
      ]
    }
  }
};

const raw = $input.item.json;

// Anthropic response: content[0].text; Gemini fallback: candidates[0].content.parts[0].text
let text = '';
if (raw?.content && Array.isArray(raw.content)) {
  text = raw.content[0]?.text || '';
} else if (raw?.candidates) {
  text = raw.candidates[0]?.content?.parts?.[0]?.text || '';
} else {
  text = raw?.text || '';
}

// Strip markdown code fences
const cleaned = text.replace(/^```(?:json)?\n?|```$/gm, '').trim();

// Sanitize literal control characters inside JSON string values.
// The AI often embeds Python source code with real newlines/tabs inside
// a JSON string — JSON.parse rejects those unless they are \-escaped.
function sanitizeJsonStrings(s) {
  let out = '';
  let inStr = false;
  let esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (esc) { out += ch; esc = false; continue; }
    if (ch === '\\' && inStr) { out += ch; esc = true; continue; }
    if (ch === '"') { out += ch; inStr = !inStr; continue; }
    if (inStr && code < 0x20) {
      // Escape literal control char
      if (code === 0x0a) out += '\\n';
      else if (code === 0x0d) out += '\\r';
      else if (code === 0x09) out += '\\t';
      else out += '\\u' + code.toString(16).padStart(4, '0');
      continue;
    }
    out += ch;
  }
  return out;
}

let ai;
try {
  ai = JSON.parse(sanitizeJsonStrings(cleaned));
} catch (e) {
  // Last-resort: try raw cleaned string
  try { ai = JSON.parse(cleaned); } catch (_) {
    ai = {
      root_cause: 'Parse error: ' + e.message,
      fix_summary: 'Manual review needed',
      patched_code: '',
      risk: 'high'
    };
  }
}

const context = $('Compose AI Input1').item.json;
return {
  json: {
    ai,
    incident: context.incident,
    github: context.github,
    repo_file_sha: context.repo_file_sha
  }
};

const { ai, incident, github, repo_file_sha } = $input.item.json;
const safeRisk = ['low', 'medium'].includes(ai.risk);
const hasPatch = typeof ai.patched_code === 'string' && ai.patched_code.trim().length > 0;
const ok = safeRisk && hasPatch;
return {
  json: {
    ok,
    reason: ok ? '' : (!hasPatch ? 'AI did not return a patch' : 'Risk level too high: ' + ai.risk),
    ai,
    incident,
    github,
    repo_file_sha,
    branch: 'ai-fix-' + Date.now()
  }
};

// Email skipped (no SMTP configured) — log incident for manual review
const d = $input.item.json;
console.log('[MANUAL REVIEW NEEDED]', JSON.stringify({
  incident: d.incident?.name,
  severity: d.incident?.severity,
  reason: d.reason,
  root_cause: d.ai?.root_cause,
  risk: d.ai?.risk
}, null, 2));
return { json: { ...$input.item.json, notification_sent: false, notification_skipped: 'no_smtp' } };

// Email skipped (no SMTP configured) — log PR creation success
const d = $input.item.json;
console.log('[AI FIX PR CREATED]', JSON.stringify({
  incident: d.incident?.name,
  pr_url: d.html_url || d.pr_url || 'unknown',
  branch: d.branch,
  risk: d.ai?.risk
}, null, 2));
return { json: { ...$input.item.json, notification_sent: false, notification_skipped: 'no_smtp' } };

// Base64-encode the patched file and build both the commit + PR payloads.
// Buffer is available in Code nodes (not in expression fields).
const pv = $('Patch Validator1').item.json;
const encoded = Buffer.from(pv.ai.patched_code || '', 'utf8').toString('base64');

const commitPayload = JSON.stringify({
  message: 'AI fix: ' + (pv.ai.fix_summary || 'automated patch'),
  content: encoded,
  sha: pv.repo_file_sha,
  branch: pv.branch
});

const prPayload = JSON.stringify({
  title: 'AI incident fix: ' + pv.incident.name,
  head: pv.branch,
  base: 'main',
  body: [
    '**Root cause:** ' + pv.ai.root_cause,
    '',
    '**Fix summary:** ' + pv.ai.fix_summary,
    '',
    '**Risk:** ' + pv.ai.risk,
    '',
    '_Automatically generated by the incident-repair workflow._'
  ].join('\n')
});

return {
  json: {
    commit_payload: commitPayload,
    pr_payload: prPayload,
    github: pv.github,
    incident: pv.incident,
    ai: pv.ai,
    branch: pv.branch
  }
};
